  const top = Object.values(c.cves).sort((a, b) => (c.epss[b.id]?.epss || 0) - (c.epss[a.id]?.epss || 0)).slice(0, 12);
  const lines = [...c.kev.slice(0, 12).map(k => `KEV added ${k.added}: ${k.id} ${k.vendor} ${k.product} – ${k.name}${k.ransomware ? ' (ransomware use)' : ''}`),
    ...top.map(x => `CVE ${x.id} CVSS ${x.cvss ?? '?'} EPSS ${((c.epss[x.id]?.epss || 0) * 100).toFixed(1)}%${x.watch?.length ? ' WATCHLIST ' + x.watch.join('/') : ''}: ${x.desc.slice(0, 160)}`),
    ...c.advisories.slice(0, 8).map(a => `${a.source}: ${a.title}`)].join('\n');
  try {
    const r = await H.httpRequest({ method: 'POST', url: `${V.ollamaUrl}/api/chat`, json: true, timeout: 300000,
      body: { model: V.model, stream: false, think: false, keep_alive: '2m', options: { num_ctx: 16384, temperature: 0.1 },
        messages: [{ role: 'user', content: `Write today's vulnerability picture in English: 4-6 one-sentence bullets. Lead with newly KEV-listed (actively exploited) bugs and ransomware use, then high-EPSS or critical CVEs, then anything marked WATCHLIST (software I use). Mention CVE IDs. Use only this data.\n\n${lines}` }] } });
    c.summary = { text: (r.message?.content || '').trim(), at: now, sig };
  } catch (e) { log.push('summary: ' + e.message); }
}

if (V.ntfyTopic) for (const x of Object.values(c.cves)) {
  if (c.pushed[x.id] || !x.watch?.length || !(x.kev || (x.cvss ?? 0) >= 9)) continue;
  try { await H.httpRequest({ method: 'POST', url: `${V.ntfyServer}/${V.ntfyTopic}`, body: `${x.watch.join(', ')} · CVSS ${x.cvss ?? '?'}${x.kev ? ' · actively exploited (KEV)' : ''}\n${x.desc.slice(0, 200)}`,
    headers: { Title: `${x.id} affects your stack`, Priority: x.kev ? '5' : '4', Tags: 'warning', Click: `https://nvd.nist.gov/vuln/detail/${x.id}` } }); c.pushed[x.id] = now; }
  catch (e) { log.push('push: ' + e.message); }
}

const env = (k) => { try { return $env[k] || ''; } catch (e) { return ''; } };

try {
  const gh = env('GITHUB_TOKEN');
  const r = await H.httpRequest({ url: 'https://api.github.com/advisories?type=reviewed&sort=published&direction=desc&per_page=60', json: true, timeout: 30000,
    headers: { 'User-Agent': 'local-threat-intel', Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28', ...(gh ? { Authorization: `Bearer ${gh}` } : {}) } });
  c.ghsa = (r || []).map(a => {
    const pk = (a.vulnerabilities || []).map(v => `${v.package?.ecosystem || ''}:${v.package?.name || ''}`).filter(s => s !== ':');
    return { id: a.ghsa_id, cve: a.cve_id || '', summary: a.summary || '', severity: a.severity || '', cvss: a.cvss?.score ?? a.cvss_severities?.cvss_v3?.score ?? null,
      epss: a.epss?.percentage ?? null, packages: [...new Set(pk)].slice(0, 6), published: a.published_at, url: a.html_url, watch: watchHit(a.summary + ' ' + pk.join(' ')) };
  });
} catch (e) { c.errors.GitHub = e.message; }

for (const [key, path] of [['euvdExploited', 'exploitedvulnerabilities'], ['euvdCritical', 'criticalvulnerabilities']]) {
  try {
    const r = await get(`https://euvdservices.enisa.europa.eu/api/${path}`, true, 30000);
    c[key] = (Array.isArray(r) ? r : r.items || []).map(v => ({ id: v.id, cves: String(v.aliases || '').split(/\s+/).filter(z => /^CVE-/.test(z)),
      desc: String(v.description || '').slice(0, 400), score: v.baseScore ?? null, epss: v.epss ?? null, published: v.datePublished, exploitedSince: v.exploitedSince || '',
      vendor: (v.enisaIdVendor || []).map(z => z.vendor?.name).filter(Boolean).join(', '), product: (v.enisaIdProduct || []).map(z => z.product?.name).filter(Boolean).join(', ') }));
  } catch (e) { c.errors['ENISA EUVD'] = e.message; }
}
const euExploited = new Set((c.euvdExploited || []).flatMap(v => v.cves));
for (const k of c.kev) k.eu = euExploited.has(k.id);

try {
  const r = await get('https://api.ransomware.live/v2/recentvictims', true, 30000);
  c.ransomware = (Array.isArray(r) ? r : r.data || []).slice(0, 100).map(v => ({ victim: v.victim || v.post_title || '?', group: v.group || v.group_name || '?',
    country: v.country || '', sector: v.activity || v.sector || '', date: v.discovered || v.attackdate || v.published || '', domain: v.domain || v.website || '',
    desc: String(v.description || '').slice(0, 300) }));
  if (V.ntfyTopic) for (const v of c.ransomware.filter(v => v.country === V.ransomwareCountry)) {
    const key = 'rw:' + v.group + ':' + v.victim; if (c.pushed[key]) continue;
    try { await H.httpRequest({ method: 'POST', url: `${V.ntfyServer}/${V.ntfyTopic}`, body: `${v.group} claims ${v.victim}${v.sector ? ' (' + v.sector + ')' : ''}`,
      headers: { Title: `Ransomware victim in ${V.ransomwareCountry}`, Priority: '3', Tags: 'skull' } }); c.pushed[key] = now; } catch (e) {}
  }
} catch (e) { c.errors['ransomware.live'] = e.message; }
c.keys = { github: !!env('GITHUB_TOKEN') };
c.ranAt = now;
fs.writeFileSync(V.cacheFile, JSON.stringify(c), 'utf8');
return [{ json: { ok: true, log, kevRecent: c.kev.length, cves: Object.keys(c.cves).length, errors: c.errors } }];

const fs = require('fs');

const Y = {
  cacheFile: '/home/node/.n8n/mailapp-youtube.json',
  ollamaUrl: 'http://host.docker.internal:11434',
  model: 'qwen3.5:9b',
  everyMin: 60,
  daysBack: 7,
  maxNewPerRun: 4,
  skipShorts: true,
  channels: [
    '@NetworkChuck', '@LiveOverflow', '@_JohnHammond', '@TwoMinutePapers', '@Fireship',
  ],
};
const S = { googleMcpUrl: 'http://mcp-youtube:8000/mcp' };

const helpers = this.helpers;
let sid = null; let nextId = 0;
const parseBody = (body) => {
  if (Buffer.isBuffer(body)) body = body.toString('utf8');
  if (typeof body !== 'string') return body || {};
  const t = body.trim();
  if (t.startsWith('{')) return JSON.parse(t);
  const datas = t.split('\n').filter(l => l.startsWith('data:')).map(l => l.slice(5).trim());
  for (const d of datas.reverse()) { try { const j = JSON.parse(d); if (j.result || j.error) return j; } catch (e) {} }
  return {};
};
async function rpc(method, params, notify = false) {
  const headers = { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' };
  if (sid) headers['mcp-session-id'] = sid;
  const msg = notify ? { jsonrpc: '2.0', method, params } : { jsonrpc: '2.0', id: ++nextId, method, params };
  const res = await helpers.httpRequest({ method: 'POST', url: S.googleMcpUrl, headers, body: JSON.stringify(msg),
    json: false, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 120000 });
  const h = res.headers || {};
  sid = sid || h['mcp-session-id'] || h['Mcp-Session-Id'];
  if (notify) return null;
  const j = parseBody(res.body);
  if (j.error) throw new Error(j.error.message || JSON.stringify(j.error));
  return j.result;
}
async function mcpInit() {
  await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'n8n-gmail-organizer', version: '1' } });
  await rpc('notifications/initialized', {}, true);
}
async function tool(name, args) {
  const r = await rpc('tools/call', { name, arguments: args });
  const text = (r?.content || []).map(c => c.text || '').join('\n').trim();
  if (/ACTION REQUIRED|Authentication Needed/i.test(text)) throw new Error('Google sign-in needed (see README: Google sign-in link)');
  if (r?.isError) throw new Error(text.slice(0, 400));
  return text;
}

const load = () => { try { return JSON.parse(fs.readFileSync(Y.cacheFile, 'utf8')); } catch (e) { return {}; } };
const c = load(); const now = Date.now(); const log = [];
if (c.ranAt && now - c.ranAt < Y.everyMin * 60000) return [{ json: { ok: true, skipped: 'ran recently' } }];
c.ids = c.ids || {}; c.videos = c.videos || []; c.errors = {};
const H = this.helpers; const UA = { 'User-Agent': 'Mozilla/5.0', 'Accept-Language': 'en' };
const decode = (t) => (t || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').trim();
const tag = (b, n) => { const m = b.match(new RegExp(`<${n}[^>]*>([\\s\\S]*?)</${n}>`, 'i')); return m ? m[1] : ''; };

for (const ch of Y.channels) {
  if (/^UC[\w-]{22}$/.test(ch)) { c.ids[ch] = ch; continue; }
  if (c.ids[ch]) continue;
  try {
    let html = await H.httpRequest({ url: `https://www.youtube.com/${ch.startsWith('@') ? ch : '@' + ch}`, json: false, timeout: 20000, headers: UA });
    html = String(html);
    const m = html.match(/<link rel="canonical" href="https:\/\/www\.youtube\.com\/channel\/(UC[\w-]{22})"/) || html.match(/"externalId":"(UC[\w-]{22})"/) || html.match(/"channelId":"(UC[\w-]{22})"/);
    if (m) c.ids[ch] = m[1]; else c.errors[ch] = 'channel ID not found';
  } catch (e) { c.errors[ch] = e.message.slice(0, 120); }
}

const since = now - Y.daysBack * 864e5; const found = [];
for (const ch of Y.channels) {
  const id = c.ids[ch]; if (!id) continue;
  try {
    const xml = String(await H.httpRequest({ url: `https://www.youtube.com/feeds/videos.xml?channel_id=${id}`, json: false, timeout: 20000, headers: UA }));
    const chName = decode(tag(xml.split('<entry')[0], 'title')) || ch;
    for (const e of xml.match(/<entry>[\s\S]*?<\/entry>/g) || []) {
      const vid = decode(tag(e, 'yt:videoId')); const t = Date.parse(decode(tag(e, 'published')));
      const link = (e.match(/<link rel="alternate" href="([^"]+)"/) || [])[1] || `https://www.youtube.com/watch?v=${vid}`;
      if (!vid || t < since) continue;
      if (Y.skipShorts && /\/shorts\//.test(link)) continue;
      found.push({ id: vid, channel: chName, title: decode(tag(e, 'title')), link, t, thumb: `https://i.ytimg.com/vi/${vid}/mqdefault.jpg`,
        desc: decode(tag(e, 'media:description')).slice(0, 400) });
    }
  } catch (e) { c.errors[ch] = e.message.slice(0, 120); }
}
for (const v of found) if (!c.videos.some(x => x.id === v.id)) c.videos.push(v);
c.videos = c.videos.filter(v => v.t >= now - 30 * 864e5).sort((a, b) => b.t - a.t).slice(0, 150);

const todo = c.videos.filter(v => !v.summary && !v.failed).slice(0, Y.maxNewPerRun);
if (todo.length) {
  try { await mcpInit(); } catch (e) { c.errors.transcripts = 'mcp-youtube not reachable: ' + e.message; }
  for (const v of todo) {
    let tr = '';
    try { tr = await tool('get_transcript', { url: `https://www.youtube.com/watch?v=${v.id}` }); } catch (e) { v.noTranscript = e.message.slice(0, 120); }
    const text = (tr || v.desc || '').slice(0, 24000);
    if (!text) { v.failed = true; continue; }
    try {
      const r = await H.httpRequest({ method: 'POST', url: `${Y.ollamaUrl}/api/chat`, json: true, timeout: 300000,
        body: { model: Y.model, stream: false, think: false, format: 'json', keep_alive: '2m', options: { num_ctx: 16384, temperature: 0.2 },
          messages: [{ role: 'user', content: `Summarise this YouTube video for me in English. ${tr ? 'Transcript' : 'Only the description is available'} below.
Answer only JSON {"summary":["3-5 short bullets with the actual points, not hype"],"verdict":"watch|skim|skip","why":"max 12 words","topics":["2-4 short tags"]}
Title: ${v.title} (channel: ${v.channel})

${text}` }] } });
      const o = JSON.parse(r.message?.content || '{}');
      v.summary = (Array.isArray(o.summary) ? o.summary : [String(o.summary || '')]).map(s => String(s).slice(0, 300)).slice(0, 5);
      v.verdict = ['watch', 'skim', 'skip'].includes(o.verdict) ? o.verdict : 'skim'; v.why = String(o.why || '').slice(0, 100);
      v.topics = (o.topics || []).map(String).slice(0, 4); v.fromTranscript = !!tr;
    } catch (e) { log.push(`summary ${v.id}: ${e.message}`); }
  }
}
c.ranAt = now; fs.writeFileSync(Y.cacheFile, JSON.stringify(c), 'utf8');
return [{ json: { ok: true, log, videos: c.videos.length, summarised: todo.length, errors: c.errors } }];

const fs = require('fs');
const G = { cacheFile: '/home/node/.n8n/mailapp-github.json', everyMin: 30, repos: ['your-user/your-repo'] };
const load = () => { try { return JSON.parse(fs.readFileSync(G.cacheFile, 'utf8')); } catch (e) { return {}; } };
const c = load(); const now = Date.now();
if (c.ranAt && now - c.ranAt < G.everyMin * 60000) return [{ json: { ok: true, skipped: 'ran recently' } }];
let token = ''; try { token = $env.GITHUB_TOKEN || ''; } catch (e) {}
const headers = { Accept: 'application/vnd.github+json', 'User-Agent': 'local-github-watch', 'X-GitHub-Api-Version': '2022-11-28', ...(token ? { Authorization: `Bearer ${token}` } : {}) };
const get = (path) => this.helpers.httpRequest({ url: `https://api.github.com${path}`, headers, json: true, timeout: 30000 });
c.repos = [];
for (const repo of G.repos) {
  const r = { repo, errors: {} };
  try {
    const runs = await get(`/repos/${repo}/actions/runs?per_page=20`);
    r.runs = (runs.workflow_runs || []).map(w => ({ id: w.id, name: w.name, branch: w.head_branch, event: w.event, status: w.status, conclusion: w.conclusion,
      title: w.display_title, sha: (w.head_sha || '').slice(0, 7), url: w.html_url, at: w.updated_at || w.created_at }));

    const latest = {}; for (const w of r.runs) { const k = `${w.name}@${w.branch}`; if (!latest[k]) latest[k] = w; }
    r.health = Object.values(latest);
  } catch (e) { r.errors.ci = /403|Resource not accessible/i.test(e.message) ? 'token lacks "Actions: Read-only" permission' : e.message.slice(0, 120); }
  try {
    const items = await get(`/repos/${repo}/issues?state=open&per_page=50`);
    r.issues = items.filter(i => !i.pull_request).map(i => ({ n: i.number, title: i.title, url: i.html_url, labels: (i.labels || []).map(l => l.name), at: i.updated_at }));
    r.prs = items.filter(i => i.pull_request).map(i => ({ n: i.number, title: i.title, url: i.html_url, at: i.updated_at }));
  } catch (e) { r.errors.issues = e.message.slice(0, 120); }
  try {
    const since = new Date(now - 7 * 864e5).toISOString();
    r.commits = (await get(`/repos/${repo}/commits?since=${since}&per_page=30`)).map(x => ({ sha: x.sha.slice(0, 7), msg: x.commit.message.split('\n')[0], url: x.html_url, at: x.commit.author?.date }));
    const closed = await get(`/repos/${repo}/issues?state=closed&since=${since}&per_page=50`);
    r.closedThisWeek = closed.filter(i => i.closed_at && Date.parse(i.closed_at) >= now - 7 * 864e5).map(i => ({ n: i.number, title: i.title, url: i.html_url, pr: !!i.pull_request, at: i.closed_at }));
  } catch (e) { r.errors.commits = e.message.slice(0, 120); }
  c.repos.push(r);
}
c.ranAt = now; fs.writeFileSync(G.cacheFile, JSON.stringify(c), 'utf8');
return [{ json: { ok: true, repos: c.repos.map(r => ({ repo: r.repo, runs: (r.runs || []).length, errors: r.errors })) } }];
